using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using GameClient;
using Xunit;

namespace GameClientTests
{
    // fixtures.json is generated by `node js/make-fixtures.js` from the JavaScript specification.
    public class StateHashParityTests
    {
        static readonly JsonElement Fixtures =
            JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "fixtures.json"))).RootElement;

        static string Hex(byte[] bytes) => Convert.ToHexString(bytes).ToLowerInvariant();

        static GameState StateFrom(JsonElement s)
        {
            var state = new GameState { Tick = s.GetProperty("tick").GetUInt32() };
            foreach (JsonElement u in s.GetProperty("units").EnumerateArray())
            {
                JsonElement target = u.GetProperty("target");
                state.Units.Add(new UnitState
                {
                    Id = u.GetProperty("id").GetUInt32(),
                    Team = u.GetProperty("team").GetByte(),
                    X = u.GetProperty("x").GetInt32(),
                    Y = u.GetProperty("y").GetInt32(),
                    Heading = u.GetProperty("heading").GetByte(),
                    Hp = u.GetProperty("hp").GetUInt16(),
                    Alive = u.GetProperty("alive").GetBoolean(),
                    Target = target.ValueKind == JsonValueKind.Null ? (uint?)null : target.GetUInt32(),
                    Name = new string(u.GetProperty("nameUnits").EnumerateArray().Select(c => (char)c.GetInt32()).ToArray()),
                });
            }
            return state;
        }

        [Fact]
        public void FloorDivAndTruncDiv_MatchJavaScript()
        {
            foreach (JsonElement c in Fixtures.GetProperty("div").EnumerateArray())
            {
                int a = c.GetProperty("a").GetInt32(), b = c.GetProperty("b").GetInt32();
                Assert.True(c.GetProperty("floor").GetInt32() == FixedMath.FloorDiv(a, b), $"FloorDiv({a}, {b})");
                Assert.True(c.GetProperty("trunc").GetInt32() == FixedMath.TruncDiv(a, b), $"TruncDiv({a}, {b})");
            }
        }

        [Fact]
        public void SampleCellX_MatchesJavaScript()
        {
            foreach (JsonElement c in Fixtures.GetProperty("sampleCellX").EnumerateArray())
            {
                int world = c.GetProperty("world").GetInt32(), width = c.GetProperty("mapWidth").GetInt32();
                Assert.True(c.GetProperty("cell").GetInt32() == FixedMath.SampleCellX(world, width),
                    $"SampleCellX({world}, {width})");
            }
        }

        [Fact]
        public void Fnv1a64_MatchesJavaScript()
        {
            foreach (JsonElement c in Fixtures.GetProperty("fnv").EnumerateArray())
            {
                byte[] bytes = Convert.FromHexString(c.GetProperty("bytesHex").GetString());
                Assert.Equal(c.GetProperty("hash").GetString(), StateHash.Fnv1a64(bytes));
            }
        }

        [Fact]
        public void StateBytes_MatchJavaScriptByteForByte()
        {
            int i = 0;
            foreach (JsonElement s in Fixtures.GetProperty("states").EnumerateArray())
            {
                Assert.True(s.GetProperty("bytesHex").GetString() == Hex(StateHash.StateBytes(StateFrom(s))), $"state {i}");
                i++;
            }
        }

        [Fact]
        public void HashState_MatchesTheServerHash()
        {
            foreach (JsonElement s in Fixtures.GetProperty("states").EnumerateArray())
                Assert.Equal(s.GetProperty("hash").GetString(), StateHash.HashState(StateFrom(s)));
        }

        [Fact]
        public void HashState_IgnoresUnitOrder_AndDoesNotReorderTheInput()
        {
            GameState state = StateFrom(Fixtures.GetProperty("states")[1]);
            uint[] before = state.Units.Select(u => u.Id).ToArray();
            string hash = StateHash.HashState(state);
            Assert.Equal(before, state.Units.Select(u => u.Id).ToArray());
            state.Units.Reverse();
            Assert.Equal(hash, StateHash.HashState(state));
        }

        [Fact]
        public void ByteWriter_IsLittleEndianAndChainable()
        {
            byte[] bytes = new ByteWriter().U8(1).U16(0x0302).U32(0x07060504).I32(-2).Bool(true).OptU32(null).OptU32(9).ToBytes();
            Assert.Equal("01020304050607feffffff010001" + "09000000", Hex(bytes));
        }

        [Fact]
        public void ByteWriter_RejectsOutOfRangeValues()
        {
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().U8(256));
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().U8(-1));
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().U16(65536));
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().U32(4294967296L));
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().U32(-1));
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().I32(2147483648L));
            Assert.Throws<ArgumentOutOfRangeException>(() => new ByteWriter().I32(-2147483649L));
            Assert.Throws<ArgumentNullException>(() => new ByteWriter().Str(null));
        }

        [Fact]
        public void Str_WritesLengthPrefixedUtf8()
        {
            Assert.Equal("0000", Hex(new ByteWriter().Str("").ToBytes()));
            Assert.Equal("0300c3a961", Hex(new ByteWriter().Str("éa").ToBytes()));
            Assert.Equal("0400f09f9a80", Hex(new ByteWriter().Str("🚀").ToBytes()));
        }
    }
}
